INSERT INTO `WarningLetter` (`id`, `employeeId`, `level`, `reason`, `description`, `issuedDate`, `validUntil`, `status`, `createdAt`, `updatedAt`) VALUES ('cmldv14bw0001q92os4f2fk5z', 'cmlbzpo2d0004x86r9ygiamib', 1, 'terlambat', '"Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum." ', '2026-02-08 14:50:19.820', '2026-03-08 00:00:00.000', 'ACTIVE', '2026-02-08 14:50:19.820', '2026-02-08 14:50:19.820');
